// ---- queue.js ----

// The queue itself, without a window: what a print job holds, how it moves between statuses, how the board sorts
// them, what a model's page shows for a person's jobs on it, and who already has a model queued.

/** The board's columns, in order. */
export const STATUSES = ["queued", "printing", "printed", "failed"];

/** Statuses a print is still waiting for or happening in: the ones that warn someone queueing the same model. */
export const ACTIVE = new Set(["queued", "printing"]);

/** A job's key among the user's shared entries. */
export const JOB = "job:";

const TONES = { queued: "waiting", printing: "active", printed: "done", failed: "failed" };

/** A short id, without crypto.randomUUID, which a Thingport instance on plain http doesn't have. */
export function newId(now = Date.now(), random = Math.random) {
  return `${now.toString(36)}${random().toString(36).slice(2, 8)}`;
}

/** A model, and the file picked on its page, as a job in the queue. */
export function newJob(model, file, now = new Date()) {
  return {
    status: "queued",
    modelId: model.id,
    name: model.name,
    fileId: file?.id ?? null,
    fileName: file?.name ?? null,
    note: "",
    queuedAt: now.toISOString(),
    startedAt: null,
    finishedAt: null,
  };
}

const text = (value) => typeof value === "string";
const maybeText = (value) => value === null || typeof value === "string";

/** Whether a shared value is a job this tool wrote, whole: anyone can write anything, and the board sorts by these. */
export function isJob(value) {
  return (
    Boolean(value) &&
    typeof value === "object" &&
    STATUSES.includes(value.status) &&
    text(value.name) &&
    text(value.modelId) &&
    text(value.queuedAt) &&
    maybeText(value.startedAt) &&
    maybeText(value.finishedAt) &&
    maybeText(value.fileId) &&
    maybeText(value.fileName) &&
    text(value.note)
  );
}

/** The job in another status, with the times that status keeps. */
export function moved(job, status, now = new Date()) {
  const at = now.toISOString();
  // Back in the queue: at its end, as though queued now.
  if (status === "queued") return { ...job, status, queuedAt: at, startedAt: null, finishedAt: null };
  if (status === "printing") return { ...job, status, startedAt: at, finishedAt: null };
  return { ...job, status, finishedAt: at };
}

/** When its status last changed. */
export function statusDate(job) {
  return job.finishedAt ?? job.startedAt ?? job.queuedAt;
}

// Which of a person's jobs on a model their chip shows: one printing, then one queued, then the latest finished.
const RANK = { printing: 0, queued: 1, printed: 2, failed: 2 };

/** What a model's page shows for a person's jobs on it, or null for none. */
export function summaryOf(jobs) {
  if (!jobs.length) return null;
  const [shown] = jobs.toSorted(
    (a, b) => RANK[a.status] - RANK[b.status] || statusDate(b).localeCompare(statusDate(a)),
  );
  return { label: `status.${shown.status}`, tone: TONES[shown.status], date: statusDate(shown) };
}

/** A model page's chips: each person with jobs on the model, or on a copy of it, once with what their jobs come to; the
 *  user first, then by name. */
export function chipsOf(entries) {
  const byPerson = new Map();
  for (const entry of entries) {
    if (!entry.key.startsWith(JOB) || !isJob(entry.value)) continue;
    const id = entry.user?.id ?? (entry.mine ? "me" : "someone");
    const person = byPerson.get(id) ?? { user: entry.user, mine: entry.mine, jobs: [] };
    person.jobs.push(entry.value);
    byPerson.set(id, person);
  }
  return [...byPerson.values()]
    .map(({ user, mine, jobs }) => ({ user, mine, summary: summaryOf(jobs) }))
    .toSorted((a, b) => Number(b.mine) - Number(a.mine) || (a.user?.name ?? "").localeCompare(b.user?.name ?? ""));
}

/** Shared entries that are jobs, with each one's user, in the board's columns: the queue oldest first, as it's worked
 *  through, and the rest newest first. `who` keeps only one person's, by id. */
export function columns(entries, who = null) {
  const jobs = entries.filter((entry) => entry.key.startsWith(JOB) && isJob(entry.value));
  const mine = who ? jobs.filter((entry) => entry.user?.id === who) : jobs;
  return Object.fromEntries(
    STATUSES.map((status) => {
      const here = mine.filter((entry) => entry.value.status === status);
      here.sort((a, b) =>
        status === "queued"
          ? a.value.queuedAt.localeCompare(b.value.queuedAt)
          : statusDate(b.value).localeCompare(statusDate(a.value)),
      );
      return [status, here];
    }),
  );
}

/** The people with jobs on the board, the user first, each once. */
export function people(entries) {
  const seen = new Map();
  for (const entry of entries) {
    if (!entry.user || !entry.key.startsWith(JOB) || seen.has(entry.user.id)) continue;
    seen.set(entry.user.id, { ...entry.user, mine: entry.mine });
  }
  return [...seen.values()].sort((a, b) => Number(b.mine) - Number(a.mine) || a.name.localeCompare(b.name));
}

/** Who already has the model waiting or printing: the others, and the user's own, from entries about it. */
export function clashes(entries) {
  const active = entries.filter(
    (entry) => entry.key.startsWith(JOB) && isJob(entry.value) && ACTIVE.has(entry.value.status),
  );
  return { others: active.filter((entry) => !entry.mine), mine: active.filter((entry) => entry.mine) };
}

/** A read of shared entries gives 5,000 at most, newest first. */
const PAGE = 5000;

/** Everyone's jobs, or those on a model (`{ model }`), read on page by page, so an old one still queued can't fall
 *  off behind newer ones. */
export async function allJobs(shared, options = {}, page = PAGE) {
  let read = await shared.list({ ...options, prefix: JOB });
  const all = [...read];
  while (read.length >= page) {
    read = await shared.list({ ...options, prefix: JOB, before: read.at(-1).cursor });
    all.push(...read);
  }
  return all;
}

/** Their names, each once: "Dad", "Dad and Mum", "Dad, Mum and Ann". */
export function listNames(entries, and) {
  const names = [...new Set(entries.map((entry) => entry.user?.name).filter(Boolean))];
  if (names.length < 2) return names[0] ?? "";
  return `${names.slice(0, -1).join(", ")} ${and} ${names.at(-1)}`;
}

/**
 * Runs each write after the ones queued under the same key before it, whether they worked or not, so two quick
 * changes to one entry are stored in the order they were made rather than the order their requests finish.
 */
export function writesInTurn() {
  const tails = new Map();
  return (key, write) => {
    const run = (tails.get(key) ?? Promise.resolve()).then(write);
    const tail = run.catch(() => undefined);
    tails.set(key, tail);
    void tail.then(() => {
      if (tails.get(key) === tail) tails.delete(key);
    });
    return run;
  };
}

// ---- ui.js ----

// The window: the household's prints on a board, Queued, Printing, Printed and Failed, each person's own to drag
// between columns; and "Add to print queue" from a model's page, which runs without the window.


const MORE_ICON =
  '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 8c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zm0 2c-1.1 0-2 .9-2 2s.9 2 2 2 2-.9 2-2-.9-2-2-2zm0 6c-1.1 0-2 .9-2 2s.9 2 2 2 2-.9 2-2-.9-2-2-2z"/></svg>';

const escapeHtml = (text) =>
  String(text ?? "").replace(
    /[&<>"']/g,
    (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c],
  );

/** A person's colour, from their id, so they look the same on every card. */
function personColour(id) {
  let hash = 0;
  for (const char of String(id)) hash = (hash * 31 + char.charCodeAt(0)) >>> 0;
  return `hsl(${hash % 360} 45% 45%)`;
}

function avatar(user) {
  const name = user?.name ?? "?";
  const style = `--pq-person: ${personColour(user?.id ?? name)}`;
  const inner = user?.avatarUrl
    ? `<img src="${escapeHtml(user.avatarUrl)}" alt="">`
    : escapeHtml(name.trim().slice(0, 1).toUpperCase() || "?");
  return `<span class="pq-av" style="${style}" aria-hidden="true">${inner}</span>`;
}

// Writes to one entry go one after another, so the last change made is the one stored.
const inTurn = writesInTurn();

/** Saved with the model it's about, so others' copies of it find it; without, once that model is gone. `job` can be a
 *  function giving it when its turn comes. Gives back what was saved. */
function saveJob(shared, key, job) {
  return inTurn(key, async () => {
    const value = typeof job === "function" ? job() : job;
    try {
      await shared.set(key, value, { model: value.modelId });
    } catch (error) {
      if (!/no such model/i.test(error?.message ?? "")) throw error;
      await shared.set(key, value);
    }
    return value;
  });
}

/** The jobs on a model and its copies, everyone's that reach the user; none for a model deleted since. */
async function jobsOn(shared, modelId) {
  try {
    return await allJobs(shared, { model: modelId });
  } catch (error) {
    if (/no such model/i.test(error?.message ?? "")) return [];
    throw error;
  }
}

/** "Add to print queue", from a model's page: asks first when someone has the model waiting or printing already. */
export async function run(command, thingport) {
  if (command !== "queue") return;
  const { models, shared, ui, t, context } = thingport;
  const model = await models.get(context.modelId);
  const { others, mine } = clashes(await allJobs(shared, { model: model.id }));
  if (others.length || mine.length) {
    const printing = others.filter((entry) => entry.value.status === "printing");
    const title = printing.length
      ? t("dup.printing", { names: listNames(printing, t("and")) })
      : others.length
        ? t("dup.queued", { names: listNames(others, t("and")) })
        : t("dup.mine");
    const message = t(others.length ? "dup.message" : "dup.again", { name: model.name });
    if (!(await ui.confirm({ title, message, confirmLabel: t("dup.add") }))) return;
  }
  const file = model.files.find((candidate) => candidate.id === context.fileId) ?? null;
  await saveJob(shared, `${JOB}${newId()}`, newJob(model, file));
  ui.toast(t("toast.queued", { name: model.name }), "success");
}

const TONE_COLOURS = {
  waiting: "var(--tp-info)",
  active: "var(--tp-warning)",
  done: "var(--tp-success)",
  failed: "var(--tp-error)",
};

const PART_CSS = `
.pqp{display:flex;flex-direction:column;gap:4px;font-family:var(--tp-font);color:var(--tp-text)}
.pqp-title{font-size:12px;color:var(--tp-text-muted)}
.pqp-chips{display:flex;flex-wrap:wrap;gap:6px}
.pqp-chip{display:inline-flex;align-items:center;gap:6px;height:26px;padding:0 10px 0 3px;border:1px solid var(--tp-divider);
  border-radius:13px;background:none;color:var(--tp-text);font:inherit;font-size:12.5px;line-height:1;cursor:pointer}
.pqp-chip:hover{background:color-mix(in srgb,var(--tp-text) 7%,transparent)}
.pqp-chip:focus-visible{outline:2px solid var(--tp-accent);outline-offset:2px}
.pqp-add{border-style:dashed;padding:0 10px 0 8px;color:var(--tp-text-muted)}
.pqp-dot{width:8px;height:8px;border-radius:50%;flex-shrink:0}
.pqp-skeleton{width:96px;height:26px;border-radius:13px;background:var(--tp-divider);animation:pqp-pulse 1s ease-in-out infinite alternate}
.pqp .pq-av{width:20px;height:20px;border-radius:50%;flex-shrink:0;display:inline-flex;align-items:center;justify-content:center;
  font-size:10px;font-weight:700;color:#fff;background:var(--pq-person);overflow:hidden}
.pqp .pq-av img{width:100%;height:100%;object-fit:cover}
@keyframes pqp-pulse{to{opacity:.45}}
@media (prefers-reduced-motion: reduce){.pqp-skeleton{animation:none}}
`;

/**
 * The part of a model's page: one chip per person with the model, or a copy of it, in their queue, showing where their
 * prints of it are; then one that adds it to the user's. A person's chip opens the board on the model.
 */
export function modelInfo(thingport) {
  const { root, shared, ui, t, language, context } = thingport;
  root.innerHTML = `<style>${PART_CSS}</style><div class="pqp"><span class="pqp-title"></span><div class="pqp-chips"><span class="pqp-skeleton"></span></div></div>`;
  root.querySelector(".pqp-title").textContent = t("part.title");
  const chips = root.querySelector(".pqp-chips");
  let reads = 0;
  let closed = false;

  const when = (iso) => {
    const at = new Date(iso);
    return Number.isNaN(at.getTime())
      ? ""
      : at.toLocaleString(language, { day: "numeric", month: "short", hour: "2-digit", minute: "2-digit" });
  };

  function chip(person) {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "pqp-chip";
    const name = person.mine ? t("board.you") : (person.user?.name ?? t("part.someone"));
    const status = t(person.summary.label);
    const dot = TONE_COLOURS[person.summary.tone] ?? "var(--tp-text-muted)";
    button.innerHTML = `${avatar(person.user)}<span class="pqp-dot" style="background:${dot}"></span><span>${escapeHtml(status)}</span>`;
    const said = t("part.chip", { name, status, date: when(person.summary.date) });
    button.title = said;
    button.setAttribute("aria-label", said);
    button.addEventListener("click", () => ui.openWindow());
    return button;
  }

  // One add at a time, whichever button drew it: the chips are drawn again while it saves, and a second add then could
  // pass the duplicate check before the first is stored.
  let adding = false;

  function addButton() {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "pqp-chip pqp-add";
    button.textContent = `+ ${t("part.add")}`;
    button.disabled = adding;
    button.addEventListener("click", async () => {
      if (adding) return;
      adding = true;
      for (const other of chips.querySelectorAll(".pqp-add")) other.disabled = true;
      try {
        await run("queue", thingport);
      } catch (error) {
        ui.toast(t("toast.failed", { error: error?.message || String(error) }), "error");
      } finally {
        adding = false;
        for (const other of chips.querySelectorAll(".pqp-add")) other.disabled = false;
      }
    });
    return button;
  }

  async function draw() {
    const read = ++reads;
    let entries;
    try {
      entries = await jobsOn(shared, context.modelId);
    } catch {
      // A read a later one has overtaken says nothing, failing or not.
      if (!closed && read === reads) chips.replaceChildren(addButton());
      return;
    }
    if (closed || read !== reads) return;
    chips.replaceChildren(...chipsOf(entries).map(chip), addButton());
  }

  const stop = shared.onChange(() => void draw());
  void draw();
  return () => {
    closed = true;
    stop();
  };
}

export default function mount(thingport) {
  const { root, shared, models, ui, t, labels, language, context } = thingport;
  const shell = root.querySelector(".pq");
  const board = root.querySelector("#pq-board");
  const empty = root.querySelector("#pq-empty");
  const peopleBar = root.querySelector(".pq-people");
  const shareLabel = root.querySelector("#pq-share-label");

  let entries = null;
  let who = null;
  let here = new Set();
  let editing = null;
  // The note being written, kept apart from the textarea so drawing the board again doesn't lose it.
  let draft = "";
  let menu = null;
  let dragKey = null;
  let scrolled = false;
  let closed = false;
  // Changes made here and saves of them still going: a read of the board one of them may postdate is dropped, as
  // it would put back what was there before, and made again once they're saved.
  let changes = 0;
  let saving = 0;
  let saveFailed = false;
  let readAgain = false;
  // Reads of the board started, so one that ends after a later one doesn't put back what that one replaced.
  let reads = 0;
  // The user's jobs as stored, as far as the board knows: each change is saved onto this, so one still saving, which
  // may fail, isn't saved along with it.
  const stored = new Map();
  // The user's jobs being removed, which take no other change meanwhile, as it would be saved after and bring them back.
  const removing = new Set();
  // Each model's thumbnail and whether the user may open it, read as the user: the address carries their session,
  // so it's never stored in what's shared.
  const looks = new Map();
  // Models whose look-up failed for a while, as when offline, asked again on the board's next read.
  const missed = new Set();
  const look = (modelId) => {
    if (!looks.has(modelId))
      looks.set(
        modelId,
        models.get(modelId).then(
          (model) => ({ thumbnail: model.thumbnail, readable: true }),
          (error) => {
            if (!/no such model/i.test(error?.message ?? "")) missed.add(modelId);
            return { thumbnail: null, readable: false };
          },
        ),
      );
    return looks.get(modelId);
  };

  const safely =
    (fn) =>
    async (...args) => {
      try {
        await fn(...args);
      } catch (error) {
        if (!closed) ui.toast(t("toast.failed", { error: error?.message || String(error) }), "error");
      }
    };

  const dateText = (iso) => {
    const at = new Date(iso);
    if (Number.isNaN(at.getTime())) return "";
    return at.toDateString() === new Date().toDateString()
      ? at.toLocaleTimeString(language, { hour: "2-digit", minute: "2-digit" })
      : at.toLocaleDateString(language, { day: "numeric", month: "short" });
  };

  async function load() {
    const at = changes;
    const read = ++reads;
    const [all, about] = await Promise.all([
      allJobs(shared),
      context.modelId ? allJobs(shared, { model: context.modelId }).catch(() => []) : [],
    ]);
    if (closed || read !== reads) return;
    if (saving || at !== changes) {
      readAgain = true;
      if (!saving) settled();
      return;
    }
    entries = all;
    for (const modelId of missed) looks.delete(modelId);
    missed.clear();
    stored.clear();
    for (const entry of all) if (entry.mine) stored.set(entry.key, entry.value);
    here = new Set(about.map((entry) => `${entry.user?.id}:${entry.key}`));
    render();
  }
  const refresh = safely(load);

  function renderPeople() {
    const everyone = people(entries ?? []);
    const chip = (id, label, user) =>
      `<button type="button" class="pq-chip${user ? "" : " pq-plain"}" data-who="${escapeHtml(id ?? "")}" aria-pressed="${who === id}">${user ? avatar(user) : ""}<span>${escapeHtml(label)}</span></button>`;
    peopleBar.innerHTML = [
      chip(null, t("board.everyone")),
      ...everyone.map((person) => chip(person.id, person.mine ? t("board.you") : person.name, person)),
    ].join("");
  }

  function card(entry) {
    const job = entry.value;
    const li = document.createElement("li");
    li.className = `pq-card${entry.mine ? " pq-mine" : ""}${here.has(`${entry.user?.id}:${entry.key}`) ? " pq-here" : ""}`;
    // A key is the writer's own, so two people's can match: a card is known by both.
    li.dataset.who = entry.user?.id ?? "";
    li.dataset.key = entry.key;
    li.dataset.status = job.status;
    const gone = entry.mine && removing.has(entry.key);
    if (gone) li.classList.add("pq-removing");
    li.draggable = entry.mine && !gone;
    const person = entry.mine ? t("board.you") : (entry.user?.name ?? "");
    const editingThis = entry.mine && editing === entry.key;
    li.innerHTML = `
      <span class="pq-thumb" aria-hidden="true">${escapeHtml(job.name.trim().slice(0, 1).toUpperCase())}</span>
      <span class="pq-body">
        <span class="pq-name" title="${escapeHtml(job.name)}">${escapeHtml(job.name)}</span>
        <span class="pq-meta">${avatar(entry.user)}<span>${escapeHtml(person)} · ${escapeHtml(dateText(statusDate(job)))}${job.fileName ? ` · ${escapeHtml(job.fileName)}` : ""}</span></span>
        ${
          editingThis
            ? `<span class="pq-edit"><textarea aria-label="${escapeHtml(t("note.label"))}" placeholder="${escapeHtml(t("note.placeholder"))}" maxlength="2000">${escapeHtml(draft)}</textarea><div><button type="button" class="pq-cancel">${escapeHtml(t("note.cancel"))}</button><button type="button" class="pq-save">${escapeHtml(t("note.save"))}</button></div></span>`
            : job.note
              ? `<span class="pq-note">${escapeHtml(job.note)}</span>`
              : ""
        }
      </span>
      <button type="button" class="pq-more" aria-haspopup="menu" aria-label="${escapeHtml(t("card.more", { name: job.name }))}">${MORE_ICON}</button>`;
    void look(job.modelId).then(({ thumbnail }) => {
      if (!thumbnail || closed) return;
      const box = li.querySelector(".pq-thumb");
      const img = new Image();
      img.alt = "";
      img.onload = () => box.replaceChildren(img);
      img.src = thumbnail;
    });
    if (editingThis) queueMicrotask(() => li.querySelector("textarea")?.focus());
    return li;
  }

  function render() {
    renderPeople();
    if (entries === null) {
      for (const list of board.querySelectorAll(".pq-list")) list.innerHTML = '<li class="pq-skeleton"></li>'.repeat(2);
      return;
    }
    const cols = columns(entries, who);
    const any = STATUSES.some((status) => cols[status].length);
    empty.hidden = any || who !== null;
    board.hidden = !any && who === null;
    for (const col of board.querySelectorAll(".pq-col")) {
      const jobs = cols[col.dataset.status];
      col.querySelector(".pq-count").textContent = jobs.length ? String(jobs.length) : "";
      const list = col.querySelector(".pq-list");
      list.replaceChildren(...jobs.map(card));
      if (!jobs.length) list.innerHTML = `<li class="pq-none">${escapeHtml(t("board.none"))}</li>`;
    }
    // Opened from a model's page: its cards are outlined, and the first is scrolled to once.
    const first = board.querySelector(".pq-here");
    if (first && !scrolled) {
      scrolled = true;
      first.scrollIntoView({ block: "nearest" });
    }
  }

  /** One of the user's cards, by key, that can still be changed. */
  const find = (key) => entries?.find((entry) => entry.mine && entry.key === key && !removing.has(key));

  /** Once no save is going: the board is read again after a failed one, or a read dropped while they went. */
  function settled() {
    if (!saveFailed && !readAgain) return;
    saveFailed = false;
    readAgain = false;
    void refresh();
  }

  /** Counts a change made here while `write` stores it. */
  async function change(write) {
    changes += 1;
    saving += 1;
    try {
      await write();
    } catch (error) {
      saveFailed = true;
      throw error;
    } finally {
      saving -= 1;
      changes += 1;
      if (!saving) settled();
    }
  }

  /** Changes a job on the board at once, and saves `edit` made to what's stored when its turn comes; when that fails,
   *  the board goes back to what it showed before. */
  const keep = (entry, edit) => {
    const before = entry.value;
    const after = edit(before);
    entry.value = after;
    render();
    return change(async () => {
      try {
        stored.set(entry.key, await saveJob(shared, entry.key, () => edit(stored.get(entry.key) ?? before)));
      } catch (error) {
        // Unless a later change has taken its place, which is saved after it.
        if (entry.value === after) {
          entry.value = before;
          render();
        }
        throw error;
      }
    });
  };

  const move = safely(async (key, status) => {
    const entry = find(key);
    if (!entry || entry.value.status === status) return;
    const at = new Date();
    await keep(entry, (job) => moved(job, status, at));
  });

  const remove = safely(async (key) => {
    const entry = find(key);
    if (!entry) return;
    const sure = await ui.confirm({
      title: t("remove.title"),
      message: t("remove.message", { name: entry.value.name }),
      confirmLabel: t("remove.confirm"),
      destructive: true,
    });
    if (!sure || removing.has(key)) return;
    removing.add(key);
    render();
    try {
      await change(() => inTurn(key, () => shared.remove(key)));
    } catch (error) {
      removing.delete(key);
      render();
      throw error;
    }
    removing.delete(key);
    stored.delete(key);
    // By key: the board may have been read again while the question was open.
    entries = entries.filter((other) => !(other.mine && other.key === key));
    render();
  });

  const saveNote = safely(async (key, note) => {
    const entry = find(key);
    if (!entry) return endEdit();
    editing = null;
    const saved = keep(entry, (job) => ({ ...job, note: note.trim() }));
    if (due) refreshWhenIdle();
    await saved;
  });

  function closeMenu({ restore = false } = {}) {
    if (!menu) return;
    const { element, opener } = menu;
    element.remove();
    menu = null;
    if (restore) opener?.focus();
  }

  // Menus asked for: only the latest opens, once its model is looked up.
  let menus = 0;
  async function openMenu(who, key, opener) {
    closeMenu();
    const asked = ++menus;
    const entry = entries?.find((other) => other.key === key && (other.user?.id ?? "") === who);
    if (!entry) return;
    const { readable } = await look(entry.value.modelId);
    if (closed || asked !== menus) return;
    const own = entry.mine && !removing.has(key);
    const items = [];
    if (own) {
      for (const status of STATUSES)
        if (status !== entry.value.status) items.push({ label: t(`move.${status}`), act: () => move(key, status) });
      items.push({
        label: t("note.edit"),
        act: () => {
          editing = key;
          draft = entry.value.note;
          render();
        },
      });
    }
    if (readable) items.push({ label: t("card.open"), act: () => ui.openModel(entry.value.modelId) });
    if (own) items.push("hr", { label: t("remove.confirm"), act: () => remove(key), danger: true });
    if (!items.length) return;
    const element = document.createElement("div");
    element.className = "pq-menu";
    element.setAttribute("role", "menu");
    for (const item of items) {
      if (item === "hr") {
        element.append(document.createElement("hr"));
        continue;
      }
      const button = document.createElement("button");
      button.type = "button";
      button.setAttribute("role", "menuitem");
      button.textContent = item.label;
      if (item.danger) button.className = "pq-danger";
      button.addEventListener("click", () => {
        closeMenu();
        item.act();
      });
      element.append(button);
    }
    shell.append(element);
    const box = opener.getBoundingClientRect();
    const frame = shell.getBoundingClientRect();
    const left = Math.min(box.right - frame.left - element.offsetWidth, frame.width - element.offsetWidth - 8);
    element.style.left = `${Math.max(8, left)}px`;
    element.style.top = `${box.bottom - frame.top + 4}px`;
    menu = { element, opener };
    element.querySelector("button")?.focus();
  }

  // The bar: whose prints, and whom the user's reach.
  peopleBar.addEventListener("click", (event) => {
    const button = event.target.closest("[data-who]");
    if (!button) return;
    who = button.dataset.who || null;
    render();
  });

  const showAudience = (audience) => {
    shareLabel.textContent = audience.everyone
      ? t("share.everyone")
      : audience.people.length
        ? t("share.people", { count: audience.people.length })
        : t("share.onlyYou");
  };
  root.querySelector("#pq-share").addEventListener(
    "click",
    safely(async () => {
      const audience = await shared.share();
      if (audience) showAudience(audience);
    }),
  );

  // The cards: their menus, notes, and dragging the user's own between columns.
  board.addEventListener("click", (event) => {
    const li = event.target.closest(".pq-card");
    if (!li) return;
    if (event.target.closest(".pq-more"))
      return void openMenu(li.dataset.who, li.dataset.key, event.target.closest(".pq-more"));
    if (event.target.closest(".pq-save")) return void saveNote(li.dataset.key, li.querySelector("textarea").value);
    if (event.target.closest(".pq-cancel")) endEdit();
  });
  board.addEventListener("input", (event) => {
    if (event.target.matches(".pq-edit textarea")) draft = event.target.value;
  });
  board.addEventListener("dragstart", (event) => {
    const li = event.target.closest(".pq-card.pq-mine");
    if (!li) return;
    dragKey = li.dataset.key;
    li.classList.add("pq-dragging");
    event.dataTransfer.effectAllowed = "move";
    event.dataTransfer.setData("text/plain", dragKey);
  });
  board.addEventListener("dragend", () => {
    dragKey = null;
    for (const node of board.querySelectorAll(".pq-dragging, .pq-over"))
      node.classList.remove("pq-dragging", "pq-over");
  });
  board.addEventListener("dragover", (event) => {
    const col = event.target.closest(".pq-col");
    if (!col || !dragKey) return;
    event.preventDefault();
    event.dataTransfer.dropEffect = "move";
    for (const other of board.querySelectorAll(".pq-over")) if (other !== col) other.classList.remove("pq-over");
    col.classList.add("pq-over");
  });
  board.addEventListener("dragleave", (event) => {
    const col = event.target.closest(".pq-col");
    if (col && !col.contains(event.relatedTarget)) col.classList.remove("pq-over");
  });
  board.addEventListener("drop", (event) => {
    const col = event.target.closest(".pq-col");
    if (!col || !dragKey) return;
    event.preventDefault();
    col.classList.remove("pq-over");
    move(dragKey, col.dataset.status);
  });

  const onOutside = (event) => {
    if (menu && !menu.element.contains(event.target) && !menu.opener.contains(event.target)) closeMenu();
  };
  const onKey = (event) => {
    if (event.key === "Escape" && menu) {
      event.preventDefault();
      event.stopPropagation();
      closeMenu({ restore: true });
    }
  };
  document.addEventListener("pointerdown", onOutside, true);
  shell.addEventListener("keydown", onKey);

  // Others' changes show up while it's open: now and then, and on coming back to the window. Not in the middle of
  // writing a note, using a menu or dragging; a refresh due then comes once the note is done.
  let due = false;
  const refreshWhenIdle = () => {
    due = Boolean(menu || editing || dragKey);
    if (!due) void refresh();
  };
  function endEdit() {
    editing = null;
    render();
    if (due) refreshWhenIdle();
  }
  const timer = setInterval(refreshWhenIdle, 30000);
  window.addEventListener("focus", refreshWhenIdle);

  labels();
  render();
  void refresh();
  void safely(async () => showAudience(await shared.audience()))();

  return () => {
    closed = true;
    closeMenu();
    clearInterval(timer);
    window.removeEventListener("focus", refreshWhenIdle);
    document.removeEventListener("pointerdown", onOutside, true);
    shell.removeEventListener("keydown", onKey);
  };
}
